/*
* Safeguarding test for: fix(pictorial): fix zero value flipping for different axes
* (mirrors apache/echarts PR #20557)
*
* A zero-valued pictorialBar must keep the same symbol direction (pxSign) as a
* non-zero bar in all four axis combinations:
* horizontal, horizontal+inverse, vertical, vertical+inverse.
*/

import { EChartsType } from '../src/echarts';
import { createChart } from '../test/ut/core/utHelper';

describe('pictorial zero value flipping', function () {

    let chart: EChartsType;
    afterEach(function () {
        chart && chart.dispose();
    });

    const PATH_SYMBOL = 'path://M0,0 L10,0 L10,10 L0,10 Z';
    const IMAGE_SYMBOL = 'image://data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUA'
        + 'AAAFCAYAAACNbyblAAAAHElEQVQI12P4//8/w38GIAXDIBKE0DHxgljNBAAO9TXL0Y4OHwAAAABJRU5ErkJggg==';

    const SYMBOLS: Record<string, string> = {
        path: PATH_SYMBOL,
        image: IMAGE_SYMBOL
    };

    const AXES_CASES = [
        { name: 'horizontal', horizontal: true, inverse: false },
        { name: 'horizontal, inversed', horizontal: true, inverse: true },
        { name: 'vertical', horizontal: false, inverse: false },
        { name: 'vertical, inversed', horizontal: false, inverse: true }
    ];

    Object.keys(SYMBOLS).forEach(function (symbolKind) {
        AXES_CASES.forEach(function (axesCase) {
            it('zero value should not flip ' + symbolKind + ' symbol ('
                + axesCase.name + ')', function () {
                chart = createChart({ width: 600, height: 400 });

                const catAxis = {
                    type: 'category' as const,
                    data: ['a', 'b']
                };
                const valueAxis = {
                    type: 'value' as const,
                    inverse: axesCase.inverse
                };

                chart.setOption({
                    xAxis: axesCase.horizontal ? valueAxis : catAxis,
                    yAxis: axesCase.horizontal ? catAxis : valueAxis,
                    series: [{
                        type: 'pictorialBar',
                        symbol: SYMBOLS[symbolKind],
                        symbolSize: 30,
                        animation: false,
                        data: [10, 0]
                    }]
                });

                const view = (chart as any)._chartsViews[0];
                const bars = view.group.children();
                expect(bars.length).toBe(2);

                const pxSigns = bars.map(function (bar: any) {
                    return bar.__pictorialSymbolMeta.pxSign;
                });
                // Zero-valued bar must keep the same direction as the non-zero bar.
                expect(pxSigns[1]).toBe(pxSigns[0]);

                // Also check the actually applied symbol scale sign on the value axis.
                const valueIdx = axesCase.horizontal ? 0 : 1;
                const scaleSigns = bars.map(function (bar: any) {
                    const symbolEl = bar.__pictorialBundle.children()[0];
                    const scale = valueIdx === 0 ? symbolEl.scaleX : symbolEl.scaleY;
                    return Math.sign(scale);
                });
                expect(scaleSigns[1]).toBe(scaleSigns[0]);
            });
        });
    });
});

